import "@/App.css";
import { lazy, Suspense } from "react";
import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import Navigation from "@/components/sections/Navigation";
import Footer from "@/components/sections/Footer";

const HomePage = lazy(() => import("@/pages/HomePage"));
const ServicePage = lazy(() => import("@/pages/ServicePage"));
const ClusterPage = lazy(() => import("@/pages/ClusterPage"));
const AboutPage = lazy(() => import("@/pages/AboutPage"));
const BlogsPage = lazy(() => import("@/pages/BlogsPage"));
const BlogPage = lazy(() => import("@/pages/BlogPage"));
const CaseStudiesPage = lazy(() => import("@/pages/CaseStudiesPage"));
const CaseStudyPage = lazy(() => import("@/pages/CaseStudyPage"));
const ContactPage = lazy(() => import("@/pages/ContactPage"));
const AdminLogin = lazy(() => import("@/pages/AdminLogin"));
const AdminDashboard = lazy(() => import("@/pages/AdminDashboard"));
const BlogManagement = lazy(() => import("@/pages/BlogManagement"));
const CaseStudyManagement = lazy(() => import("@/pages/CaseStudyManagement"));
const NotFoundPage = lazy(() => import("@/pages/NotFoundPage"));

function App() {
  return (
    <div style={{ overflowX: 'hidden' }}>
      <BrowserRouter>
        <Suspense fallback={<div style={{ minHeight: '100vh' }} />}>
          <Routes>
            <Route path="/" element={
              <>
                <Navigation />
                <HomePage />
                <Footer />
              </>
            } />
            <Route path="/about" element={
              <>
                <Navigation />
                <AboutPage />
                <Footer />
              </>
            } />
            <Route path="/blogs" element={
              <>
                <Navigation />
                <BlogsPage />
                <Footer />
              </>
            } />
            <Route path="/blog/:slug" element={
              <>
                <Navigation />
                <BlogPage />
                <Footer />
              </>
            } />
            <Route path="/case-studies" element={
              <>
                <Navigation />
                <CaseStudiesPage />
                <Footer />
              </>
            } />
            <Route path="/case-study/:id" element={
              <>
                <Navigation />
                <CaseStudyPage />
                <Footer />
              </>
            } />
            <Route path="/contact" element={
              <>
                <Navigation />
                <ContactPage />
                <Footer />
              </>
            } />

            {/* The Wikipedia subpage moved to a descriptive slug */}
            <Route path="/solutions/geo/wikipedia" element={<Navigate to="/solutions/geo/wikipedia-page-creation" replace />} />

            {/* The SEO community/UGC page was retired; Quora & review-platform work
                now lives under GEO. Mirrors the 301 in vercel.json. */}
            <Route path="/solutions/seo/community-ugc-search-amplification" element={<Navigate to="/solutions/geo/quora-content-seeding" replace />} />

            {/* Redirect the removed White Label pillar to Full Stack Development */}
            <Route path="/solutions/white-label" element={<Navigate to="/solutions/full-stack" replace />} />
            <Route path="/solutions/white-label/*" element={<Navigate to="/solutions/full-stack" replace />} />

            {/* Redirect the removed AI/ML pillar — Google still has this URL indexed
                (real impressions for "ai ml solutions", "custom machine learning solutions"),
                so send it somewhere live instead of letting it 404 silently. */}
            <Route path="/solutions/ai-ml" element={<Navigate to="/solutions/ai-automations" replace />} />
            <Route path="/solutions/ai-ml/*" element={<Navigate to="/solutions/ai-automations" replace />} />

            {/* Cluster (sub-service) pages — Quora and Wikipedia now render through
                the same standard template as every other subpage (Violet + Amber
                redesign), using their existing, unmodified clusterPagesData content. */}
            <Route path="/solutions/:pillar/:cluster" element={
              <>
                <Navigation />
                <ClusterPage />
                <Footer />
              </>
            } />

            {/* Pillar page */}
            <Route path="/solutions/:slug" element={
              <>
                <Navigation />
                <ServicePage />
                <Footer />
              </>
            } />

            <Route path="/admin" element={<AdminLogin />} />
            <Route path="/admin/dashboard" element={<AdminDashboard />} />
            <Route path="/admin/blogs" element={<BlogManagement />} />
            <Route path="/admin/case-studies" element={<CaseStudyManagement />} />

            {/* Common near-miss URLs */}
            <Route path="/blog" element={<Navigate to="/blogs" replace />} />
            <Route path="/case-study" element={<Navigate to="/case-studies" replace />} />

            <Route path="*" element={
              <>
                <Navigation />
                <NotFoundPage />
                <Footer />
              </>
            } />
          </Routes>
        </Suspense>
      </BrowserRouter>
    </div>
  );
}

export default App;
